CREATE TABLE music_queue (id UUID PRIMARY KEY DEFAULT uuid_v7(), owner_id UUID NOT NULL, shuffle_enabled BOOLEAN NOT NULL DEFAULT FALSE, shuffle_seed BIGINT, repeat_mode VARCHAR(16) NOT NULL DEFAULT 'OFF', current_entry_id UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp, updated_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp, version BIGINT NOT NULL DEFAULT 0, CHECK(repeat_mode IN ('OFF','QUEUE','ONE')), CHECK(version>=0));
CREATE TABLE music_queue_entry (id UUID PRIMARY KEY DEFAULT uuid_v7(), queue_id UUID NOT NULL, track_id UUID NOT NULL, base_position INTEGER NOT NULL, active_position INTEGER NOT NULL, inserted_by UUID NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp, CHECK(base_position>=0),CHECK(active_position>=0),FOREIGN KEY(queue_id) REFERENCES music_queue(id) ON DELETE CASCADE,FOREIGN KEY(track_id) REFERENCES music_track(id));
CREATE INDEX idx_music_queue_entry_order ON music_queue_entry(queue_id,active_position);
